  const skillDialog=h('dialog',{id:'aiSkillDialog',class:'app-dialog feature-dialog ai-drill-dialog'});
  skillDialog.innerHTML=`<div class="dialog-frame feature-dialog-frame ai-frame"><header><div><p class="eyebrow">Skills</p><h2 id="skillDialogTitle">Add skill with AI</h2><p>Describe what you want to learn. You will preview the progression before it is saved.</p></div><button class="icon-button" data-close type="button">×</button></header><div class="ai-prompt-box"><textarea id="skillPrompt" rows="6" placeholder="Example: I want to improve my forehand counterloop against medium topspin. Start slowly and add placement variation."></textarea><div class="ai-prompt-actions"><button id="skillGenerateBtn" class="button primary" type="button">Generate progression</button></div></div><details class="feature-details"><summary>AI options</summary><div class="field-grid two"><label class="field"><span>Method</span><select id="skillAiMode"><option value="builtin">Built-in assistant</option><option value="byok">Use my API key</option><option value="external">Use another AI manually</option></select></label><label class="field"><span>Provider</span><select id="skillProvider"><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option><option value="gemini">Google Gemini</option><option value="openrouter">OpenRouter</option></select></label><label class="field"><span>API key (session only)</span><input id="skillKey" type="password" autocomplete="off" placeholder="Not saved"></label><label class="field"><span>Model ID</span><input id="skillModel" type="text" autocomplete="off" placeholder="Provider model ID"></label></div><p class="helper">The API key is kept only in memory. Manual mode copies a complete request; paste the AI response below.</p><textarea id="skillExternalResult" rows="7" placeholder="Paste the AI response here" hidden></textarea></details><div id="skillStatus" class="feature-status" aria-live="polite"></div><section id="skillProposal" class="ai-proposal" hidden><div class="section-title-row"><div><h3 id="skillProposalName"></h3><p id="skillProposalDescription"></p></div><span class="status-badge valid">Validated</span></div><div id="skillProposalSteps" class="proposal-details"></div><div class="dialog-actions"><button id="skillTryAgain" class="button ghost" type="button">Try another</button><button id="skillSaveBtn" class="button primary" type="button">Add skill</button></div></section></div>`;
